mapper.select:
SELECT IFNULL(SUM(courses.credits), 0)
FROM enrollments
JOIN lectures ON enrollments.lecture_id = lectures.id
JOIN courses ON lectures.course_id = courses.id
WHERE enrollments.student_id = #{studentId}
  AND lectures.year = #{year}
  AND lectures.semester = #{semester}
  AND enrollments.status != 'DROPPED'
